function itemTitle(i){if(!i)return 'Keine';if(i.nickname)return i.nickname+' – '+itemTitle({...i,nickname:''});/* Beinamen erbeuteter Einzelstücke (Außenwelt) */const q=clamp(i.q||0,0,6),d=definition(i);if(i.kind==='weapon')return weaponTitles[i.def]?.[q]||d?.name||'?';const set=['Flicken','Rekruten','Legionärs','Veteranen','Prätorianer','Triumph','Unsterblichen'][q];return (i.kind==='armor'?(i.material==='leather'?'Leder · ':i.material==='medium'?'Verstärkt · ':'Metall · '):'')+set+'-'+(d?.name||'?');}
// Leder wird mit jeder Qualitätsstufe dunkler, edler und stärker beschlagen; verstärkte Rüstung zeigt Metallplatten auf Leder.
const leatherLooks=[
 {metal:'#927653',edge:'#b39770',trim:'#5a4630',dark:'#5a4630',stud:'#77664c',cloth:'#695c46'},
 {metal:'#805936',edge:'#b18c59',trim:'#4e3727',dark:'#4e3727',stud:'#9a8a68',cloth:'#685646'},
 {metal:'#77492c',edge:'#b98550',trim:'#3d2a1e',dark:'#3d2a1e',stud:'#b89a62',cloth:'#456c65'},
 {metal:'#6a3d27',edge:'#b0784a',trim:'#c9a55a',dark:'#2f211a',stud:'#c9a55a',cloth:'#395e76'},
 {metal:'#5a2c22',edge:'#a35c40',trim:'#d8b45e',dark:'#261a17',stud:'#dbdccb',cloth:'#704754'},
 {metal:'#33292c',edge:'#6d5a58',trim:'#d9b65c',dark:'#17151a',stud:'#ecd184',cloth:'#446c78'},
 {metal:'#5a1c27',edge:'#a8444a',trim:'#f0cf74',dark:'#26101a',stud:'#fff0bc',gem:'#5fd0c0',cloth:'#703d68'}];
const mediumLooks=gearLooks.map((look,q)=>({...look,leather:['#6f5a43','#6b4a30','#5f3d27','#553423','#4a2a20','#352626','#42202a'][q],dark:leatherLooks[q].dark}));
function itemLook(i){return (i?.kind==='armor'&&i.material==='leather'?leatherLooks:i?.kind==='armor'&&i.material==='medium'?mediumLooks:gearLooks)[clamp(i?.q||0,0,6)];}
function itemName(i){return i?itemTitle(i)+' · '+gearQuality[i.q]+(i.kind==='weapon'&&DRAW[i.def]?' · '+drawWeight(i)+' Pfd.'+(i.rolls?.damage?' · '+buildLabel(i):''):''):'Keine';}
// ---------- Zugstärke (Pfund) bei Bögen und Armbrüsten ----------
// Bogen 30–100 Pfd., Armbrust 100–400 Pfd. Mehr Pfund = etwas mehr Schaden (die Waffenklasse bleibt wichtiger) und längeres Spannen/Nachladen
// (Stärke verkürzt es, höchstens ×1,5). Beim Bogen kostet ein zu starker Bogen Genauigkeit, wenn die Stärke fehlt – ab etwa 60 Stärke ist
// selbst ein 100-Pfund-Bogen voll beherrscht. Die Armbrust zielt unabhängig von der Stärke (der Bügel wird mit der Winde gespannt, nicht gehalten).
function clampDraw(id,lb){const D=DRAW[id];return D?Math.round(clamp(+lb||D.def,D.min,D.max)/D.step)*D.step:0}
function rollDraw(id){const D=DRAW[id];if(!D)return 0;const R=()=>{try{return rng()}catch(e){return Math.random()}},r=(R()+R()+R())/3;return clampDraw(id,D.min+(D.max-D.min)*r)}
// Fertigung: jeder Bogen / jede Armbrust weicht beim Kauf bis zu ±10 % vom Grundschaden ab (Mitte häufiger als die Ränder)
function rollBuild(){const R=()=>{try{return rng()}catch(e){return Math.random()}};return Math.round((.9+.2*(R()+R())/2)*1000)/1000}
function buildGrade(i){const r=i?.rolls?.damage??1;return r<.94?'Mangelhaft':r<.98?'Unterdurchschnittlich':r<=1.02?'Ordentlich':r<=1.06?'Gut gearbeitet':'Ausgezeichnet'}
function buildLabel(i){const r=i?.rolls?.damage??1,pc=Math.round((r-1)*100);return buildGrade(i)+' ('+(pc>0?'+':pc<0?'−':'±')+Math.abs(pc)+' %)'}
// Empfohlene Stärke: Bogen = ab hier zittert nichts mehr; Armbrust = ab hier höchstens 5 % längeres Nachladen
function drawNeed(i){const D=i&&DRAW[i.def];if(!D)return 0;if(i.def==='bow'){const k=(drawWeight(i)-30)/70;return Math.ceil(60*Math.pow(Math.max(0,k),1/.85))}const k=drawK(i);return k<=.1?0:Math.ceil(70*(1-.1/k))}
function drawWeight(i){const D=i&&DRAW[i.def];return D?clampDraw(i.def,i.lb??D.def):0}
function drawK(i){const D=i&&DRAW[i.def];return D?(drawWeight(i)-D.min)/(D.max-D.min):0}
// Reichweite (22.10., Wunsch Thomas: Bogenschützen schießen viel weiter, abhängig von der Zugstärke):
// Bogen ×1,3 (30 Pfd.) bis ×2,2 (100 Pfd.) = ca. 330–560 statt 255; Armbrust ×1,3 (100 Pfd.) bis ×2,1 (400 Pfd.) = ca. 400–650 statt 310.
function drawRange(i){const D=i&&DRAW[i.def];if(!D)return 1;const k=drawK(i);return i.def==='bow'?1.3+.9*k:1.3+.8*k}
function drawDamage(i){const D=i&&DRAW[i.def];return D?D.dmg[0]+(D.dmg[1]-D.dmg[0])*drawK(i):1}
// Wie viel Pfund hält dieser Gladiator beim Bogen sicher? 30 Pfd. ohne Kraft, 100 Pfd. ab Stärke 60
function drawComfort(g){const st=clamp(g?.stats?.strength??30,0,100);return Math.round(30+70*Math.pow(Math.min(1,st/60),.85))}
// Genauigkeit: Streuung ×1 bis etwa ×2,2, wenn der Bogen zu schwer ist (Armbrust: immer ×1)
function drawAim(g,i){if(!i||i.def!=='bow')return 1;const over=Math.max(0,drawWeight(i)-drawComfort(g));return 1+1.2*over/70}
// Spann-/Nachladezeit: ×1 bis ×1,5 – mehr Pfund dauert länger, Stärke hilft; ab Stärke 70 (gängiger Höchstwert) gar kein Nachteil mehr
function drawReload(g,i){const D=i&&DRAW[i.def];if(!D)return 1;const st=clamp(g?.stats?.strength??30,0,100);return 1+.5*drawK(i)*(1-Math.min(1,st/70))}
// Meisterschaft beim Bogen: ein geübter, kräftiger Bogenschütze schießt am Ende schneller als jede Armbrust nachladen kann
function bowMaster(g,i){if(!i||i.def!=='bow')return 1;const m=clamp((g?.mastery?.bow||0)/100,0,1),fit=Math.min(1,drawComfort(g)/Math.max(1,drawWeight(i)));return 1+.35*Math.pow(m,1.5)*fit}

function itemPrice(kind,id,q){const d=(kind==='weapon'?weaponDefs:kind==='armor'?armorDefs:shieldDefs).find(x=>x.id===id);return Math.round(gearPrices[q]*(kind==='weapon'?(d.damage/16)*.8+.2:kind==='armor'?d.weight/9+.3:d.weight/10+.55))}
function itemStats(i){if(!i)return null;const workmanship=1+clamp(i.forgeQuality||0,-.1,.1)+clamp(i.refinement?.bonus||0,0,.1),d=definition(i),f=(i.q===0?.78:Math.pow(4,(i.q-1)/5)),condition=.55+.45*clamp(i.durability/i.maxDurability,0,1);const netThickness=d.id==='net'?3.6*f*condition*(1+i.up.sharp*.005)*(i.rolls?.damage??1)*workmanship:0;return {...d,netThickness,netDuration:d.id==='net'?clamp((2.25+.63*clamp(i.q||0,0,6))*(.8+.2*clamp(i.durability/i.maxDurability,0,1))*(i.rolls?.damage??1)*workmanship,1.35,8.25):0,damage:d.damage*f*condition*(1+i.up.sharp*.005)*(i.rolls?.damage??1)*workmanship*drawDamage(i),range:d.range*(i.rolls?.range??1)*drawRange(i),delay:d.delay*(i.forgeRange?2-(i.rolls?.speed??1):1/(i.rolls?.speed??1))/(1+i.q*.012+i.up.balance*.003),weight:d.weight*(i.kind==='armor'&&i.material==='leather'?.40:i.material==='medium'?.68:1)*(1-i.q*.003)*(i.rolls?.weight??1),pen:clamp(((d.pen||0)+i.q*.01+i.up.penetration*.003)*(i.rolls?.pen??1),0,.85),protection:(d.protection||0)*(i.kind==='armor'&&i.material==='leather'?.65:i.material==='medium'?.82:1)*f*condition*(i.rolls?.protection??1)*workmanship,block:(d.block||0)*(1+i.q*.025)*(i.rolls?.block??1),area:d.area===undefined?undefined:clamp(d.area*(1+i.q*.035)*(i.rolls?.area??1),0,.78),crit:(1.45+i.q*.025)*(i.rolls?.crit??1)}}
let inventorySource=null,inventoryLength=-1,inventoryMap=new Map();function inventoryItem(id){if(!id)return undefined;if(inventorySource!==s.inventory||inventoryLength!==s.inventory.length){inventorySource=s.inventory;inventoryLength=s.inventory.length;inventoryMap=new Map(s.inventory.map(i=>[i.id,i]));}return inventoryMap.get(id)}
function allowedRanged(g,item){const id=typeof item==='string'?item:item?.def;return ({Fernkämpfer:['bow','crossbow'],Soldat:['net'],Assassine:['javelin','throwaxe']}[g.role]||[]).includes(id);}
// Nahkampfwaffe je Klasse: Fernkämpfer nur Dolch und kein Schild, Assassinen Kurzschwert, Gladius oder Axt, Soldaten alles.
const classMelee={Fernkämpfer:['dagger'],Assassine:['short','gladius','axe']};
function allowedMelee(g,item){const id=typeof item==='string'?item:item?.def,list=classMelee[g.role];return !list||list.includes(id);}
function allowedShield(g){return g.role!=='Fernkämpfer';}
function meleeRule(g){return g.role==='Fernkämpfer'?'Fernkämpfer tragen im Nahkampf nur den Dolch.':'Assassinen tragen Kurzschwert, Gladius oder Axt.';}
function normalizeClassGear(g){if(!g?.equipment)return;if(!g.enemyGear){const second=inventoryItem(g.equipment.secondary);if(second&&!allowedMelee(g,second))g.equipment.secondary=null;if(g.equipment.shield&&!allowedShield(g))g.equipment.shield=null;}const i=g.enemyGear?.weapon||inventoryItem(g.equipment.weapon);if(i&&definition(i).ammo&&!allowedRanged(g,i)){if(g.enemyGear)g.enemyGear.weapon=null;else g.equipment.weapon=null;}}
function gear(g,slot){const i=g.enemyGear?g.enemyGear[slot]:inventoryItem(g.equipment[slot]);return slot==='weapon'&&i&&definition(i).ammo&&!allowedRanged(g,i)?null:i}
function armorItems(g){return g.enemyGear?Object.values(g.enemyGear.armor||{}):Object.values(g.equipment.armor).map(inventoryItem).filter(Boolean)}
function weightGear(g){return [gear(g,'weapon'),gear(g,'secondary'),gear(g,'shield'),...armorItems(g)].filter(Boolean).reduce((v,i)=>v+definition(i).weight*(i.kind==='armor'&&i.material==='leather'?.40:i.material==='medium'?.68:1)*(1-i.q*.003)*(i.rolls?.weight??1),0)}
function health(g){let n=0,w=0;for(const [id]of parts){const k=['head','neck','chest','belly'].includes(id)?3:1;n+=(g.body[id].missing?0:g.body[id].hp)*k;w+=k}return n/w}
function legImpairment(g,side){return Math.max(0,...[side+'t',side+'sh',side+'f'].map(id=>{const p=g.body[id];return !p||p.missing?0:p.fracture?.85:clamp((70-p.hp)/45,0,1);}));}
function limb(g,ids){return ids.reduce((a,id)=>a+(g.body[id].missing?0:clamp(g.body[id].hp/(100+g.body[id].chronic),.08,1)*(g.body[id].fracture?.28:1)),0)/ids.length}
function power(g){return Math.round((Object.values(g.stats).reduce((a,b)=>a+b)/17)*(.5+health(g)/200)+(itemStats(gear(g,'secondary')||gear(g,'weapon'))?.damage||4)*.6+armorItems(g).reduce((n,i)=>n+itemStats(i).protection,0)*.15)}
function capacity(){return Math.max(60,6+s.buildings.housing*3,s.roster.length)}function storageCapacity(){return Math.max(2000,30+s.buildings.storage*15,s.inventory.length)}
function price(g){if(g.recruitStandard)return 100;return Math.round(recruitPrices[g.quality]*(.9+(power(g)/100)*.3))}function marketValue(g){return Math.round(price(g)*(1+Math.min(.8,g.fights*.008)+g.fame/300)*health(g)/100)}
function refreshMarket(force=false){if(s.blindRecruitment){s.market=[];s.lastMarket=s.day;return true;}if(!force&&s.day-s.lastMarket<3)return false;s.market=Array.from({length:6},()=>{const g=makeGladiator(0);g.price=100;g.name='Rekrut aus '+g.origin;return g});s.lastMarket=s.day;return true}if(!s.market.length)refreshMarket(true);

function equippedBy(id){return s.roster.find(g=>['weapon','secondary','shield'].some(k=>g.equipment[k]===id)||Object.values(g.equipment.armor).includes(id))}
function buyItem(kind,id,q,material='metal'){if(!Number.isInteger(q)||q<0||q>6||!(kind==='weapon'?weaponDefs:kind==='armor'?armorDefs:shieldDefs).some(d=>d.id===id))return 'Ungültiger Gegenstand.';let cost=itemPrice(kind,id,q);if(s.gold<cost)return 'Nicht genug Gold.';if(s.inventory.length>=storageCapacity())return 'Lager ist voll.';const i=makeItem(kind,id,q,material);i.durability=i.maxDurability;s.inventory.push(i);s.gold-=cost;s.stats.spent+=cost;persist();return 'Gekauft: '+itemName(i)}
function equip(gid,iid,secondary=false){const g=s.roster.find(g=>g.id===gid),i=inventoryItem(iid);if(!g||!i)return 'Gegenstand fehlt.';if(g.smithDuty)return 'Dieser Gladiator arbeitet beim Schmied und trägt keine Kampfausrüstung.';if(secondary&&i.kind==='weapon'&&!definition(i).ammo&&!allowedMelee(g,i))return meleeRule(g);if(i.kind==='shield'&&!allowedShield(g))return 'Fernkämpfer tragen keinen Schild.';if(i.kind==='weapon'&&!secondary&&definition(i).ammo&&!allowedRanged(g,i))return 'Diese Fernwaffe passt nicht zur Klasse: Fernkämpfer – Bogen/Armbrust, Soldat – Netz, Assassine – Wurfaxt/Wurfspeer.';if(secondary&&i.kind==='weapon'&&definition(i).ammo)return 'Als Hauptwaffe ist eine Nahkampfwaffe erforderlich.';if(i.kind==='weapon'&&!secondary&&!definition(i).ammo)return 'Im Fernkampfplatz sind Wurfwaffen, Netze, Bögen und Armbrüste möglich.';const owner=equippedBy(iid);if(owner){for(const k of ['weapon','secondary','shield'])if(owner.equipment[k]===iid)owner.equipment[k]=null;for(const k in owner.equipment.armor)if(owner.equipment.armor[k]===iid)delete owner.equipment.armor[k]}if(secondary&&i.kind==='weapon'&&definition(i).ammo)return 'Als Hauptwaffe ist eine Nahkampfwaffe erforderlich.';if(i.kind==='armor')g.equipment.armor[i.def]=iid;else g.equipment[i.kind==='weapon'&&secondary?'secondary':i.kind]=iid;persist();return 'Ausrüstung zugewiesen.'}
function sellItem(id){const i=inventoryItem(id);if(!i)return '';if(equippedBy(id))return 'Zuerst den Gegenstand ablegen.';const gold=Math.round(itemPrice(i.kind,i.def,i.q)*.42*(i.durability/i.maxDurability));s.gold+=gold;s.inventory=s.inventory.filter(x=>x!==i);persist();return '+'+gold+' Gold'}
function addScar(g,id,reason){if(!g.scars.some(x=>x.part===id&&x.reason===reason))g.scars.push({part:id,day:s.day,reason});}
function injuryGrade(p){return p.missing?5:p.hp<20?4:p.hp<40?3:p.hp<65?2:p.hp<90?1:0}
function noteInjury(g,id,text,attacker=null,weapon=null){if(attacker)recordWound(g,id,text,attacker,weapon);const p=g.body[id];p.injury=text;p.grade=injuryGrade(p);g.history.unshift({day:s.day,text:partName(id)+': '+text});g.history=g.history.slice(0,100)}
function kill(g,cause,killer){if(g.dead)return;g.dead=true;g.cause=cause;g.killer=killer||'Unbekannt';if(!g.enemy){const entry={id:g.id,name:g.name,age:g.age,wins:g.wins,fights:g.fights,kills:g.kills,highest:g.highest,cause,killer:g.killer,day:s.day,scars:copy(g.scars),parents:copy(g.parents||null),killHistory:copy(g.killHistory||[])};try{window.MG?.onFallen?.(g,entry);}catch(e){console.warn(e);}s.fallen.unshift(entry);s.roster=s.roster.filter(x=>x.id!==g.id);s.teams=s.teams.map(t=>t.filter(id=>id!==g.id));log(g.name+' ist gefallen: '+cause);persist()}}
// Heiltempo: alles Heilen pro Tag läuft dreimal so schnell (HP, Blut, Blutung, Schmerz, Bruch- und Innenverletzungs-Tage)
const HEAL_SPEED=3;
function advanceDay(days=1){if(s.battle)return 'Während eines Kampfes nicht möglich.';for(let d=0;d<days;d++){s.day++;window.MG?.chargeSold?.();for(const g of s.roster){g.fatigue=Math.max(0,g.fatigue-14-s.buildings.hospital);g.blood=Math.min(100,g.blood+12*HEAL_SPEED);const treatment=g.healing;for(const p of Object.values(g.body)){if(p.missing)continue;let heal=(3+s.buildings.hospital+(treatment?[0,7,16,26][treatment.tier]:0))*HEAL_SPEED;if(p.fracture){p.fracture.days=Math.min(p.fracture.days,20*HEAL_SPEED);p.fracture.days=Math.max(0,p.fracture.days-(treatment?1+treatment.tier*.2:1)*HEAL_SPEED);heal=Math.min(heal,2.5*HEAL_SPEED);if(p.fracture.skull&&p.fracture.days>0&&p.injury!=='Schädelbruch')p.injury='Schädelbruch';if(p.fracture.days>0)p.hp=Math.min(p.hp,64);else {if(p.fracture.skull){p.skullPlate=true;p.skullFracture=undefined;p.injury=null;}else addScar(g,Object.keys(g.body).find(k=>g.body[k]===p),'Verheilter Bruch');p.fracture=null;}}if(p.internal){p.internal.days=Math.max(0,p.internal.days-HEAL_SPEED);heal=Math.min(heal,2*HEAL_SPEED);if(!p.internal.days)p.internal=null;}p.hp=Math.min(p.fracture?64:p.internal?60:100-p.chronic,p.hp+heal);p.pain=Math.max(0,p.pain-heal*.7);p.bleed=Math.max(0,p.bleed-4*HEAL_SPEED);p.grade=injuryGrade(p);if(!p.fracture&&!p.internal&&p.hp>=90-p.chronic)p.injury=p.chronic?'Dauerhafte Einschränkung':''}if(treatment){treatment.days--;if(treatment.days<=0)g.healing=null}if((s.day-g.birthday)%365===0)g.age++;g.stats.morale=clamp(g.stats.morale+1,1,g.caps.stats.morale)}if(s.day-s.lastMarket>=3)refreshMarket();if(s.sponsor&&s.day>s.sponsor.until){log('Der Sponsorenvertrag ist ausgelaufen.');s.sponsor=null}window.MG?.householdDay?.()}persist();return days+' Tag'+(days>1?'e':'')+' vergangen. Erholung und Heilung angewendet.'}
function train(){return 'Gladiatoren lernen durch ihre tatsächlichen Aktionen im Kampf. Es gibt keine manuelle Punktevergabe.'}

function medicalCost(g,tier){return Math.round((15+(100-health(g))*1.8+g.scars.length*3)*[0,1,3,7][tier]*Math.max(.5,1-s.buildings.medic*.05))}
function treat(id,tier){const g=s.roster.find(g=>g.id===id);if(!g)return '';const cost=medicalCost(g,tier);if(s.gold<cost)return 'Nicht genug Gold.';s.gold-=cost;s.stats.spent+=cost;g.healing=tier?{tier,days:4}:null;for(const [id,p]of Object.entries(g.body)){p.bleed=0;if(p.missing)continue;p.hp=Math.min(p.fracture?64:p.internal?60:100-p.chronic,p.hp+[0,8,20,35][tier]);p.pain=Math.max(0,p.pain-tier*10);if(tier>0&&p.chronic>0)p.chronic=Math.min(p.chronic,Math.max(1,Math.round(p.chronic*(1-[0,.03,.08,.18][tier])*100)/100));p.grade=injuryGrade(p)}g.blood=Math.min(100,g.blood+tier*15);persist();return tier?'Behandlung begonnen. Zusätzliche Heilung an den nächsten vier Tagen.':'Natürliche Heilung gewählt.'}
function retire(id){const g=s.roster.find(g=>g.id===id);if(!g)return '';if(g.fights<5)return 'Mindestens fünf Kämpfe für eine Trainerlaufbahn nötig.';ensureCareer(g);g.retired=true;g.trainerEnabled=true;g.trainerCaps=copy(g.mastery);const specialty=g.fame>=200?'tactics':g.skills.bow>g.skills.sword?'archery':'weapons';s.trainers.push({...g,specialty});s.roster=s.roster.filter(x=>x!==g);s.teams=s.teams.map(t=>t.filter(x=>x!==id));log(g.name+' arbeitet nun als Trainer.');persist();return 'Als Trainer eingestellt.'}
function buildingCost(k){return 0}function upgradeBuilding(k){return 'Gebäude-Upgrades sind entfernt.'}
function repairCost(i){return Math.max(0,Math.ceil((i.maxDurability-i.durability)*(.3+i.q*.6)));}
function repairEquipped(){if(s.battle)return 'Während eines Kampfes nicht möglich.';const items=s.inventory.filter(i=>equippedBy(i.id)&&i.durability<i.maxDurability),cost=items.reduce((n,i)=>n+repairCost(i),0);if(!items.length)return 'Alle angelegten Gegenstände sind intakt.';if(s.gold<cost)return 'Nicht genug Gold für alle angelegten Gegenstände.';s.gold-=cost;s.stats.spent+=cost;for(const i of items)i.durability=i.maxDurability;persist();return items.length+' angelegte Gegenstände für '+cost+' Gold repariert.';}
function forge(id,type){if(s.battle)return 'Während eines Kampfes nicht möglich.';if(type!=='repair')return 'Verfeinerungen sind entfernt. Ausrüstung kann repariert werden.';const i=inventoryItem(id);if(!i)return 'Gegenstand nicht gefunden.';const c=repairCost(i);if(s.gold<c)return 'Nicht genug Gold.';s.gold-=c;s.stats.spent+=c;i.durability=i.maxDurability;persist();return 'Ausrüstung repariert.'}
function makeEvent(){s.event=null;}
function resolveEvent(yes){const e=s.event;if(!e)return '';if(e.type==='trainer'){s.event=null;persist();return 'Trainer werden ausschließlich aus deinem eigenen Ruhestand berufen.';}const g=s.roster.find(g=>g.id===e.g);if(yes&&['merchant','wages','trainer'].includes(e.type)&&s.gold<e.cost)return 'Nicht genug Gold.';if(yes){if(e.type==='sponsor')s.sponsor={name:pick(['Haus Aelius','Die Goldene Amphore','Gilde der Schmiede']),until:s.day+15,bonus:.18};if(e.type==='merchant'){if(s.inventory.length>=storageCapacity())return 'Lager ist voll.';s.gold-=e.cost;s.inventory.push(e.item)}if(e.type==='wages'){s.gold-=e.cost;if(g)g.stats.morale=Math.min(g.caps.stats.morale,g.stats.morale+15)}if(e.type==='challenge')s.challenge={reward:leagues[s.fightLeague??s.league].reward*1.8,league:s.fightLeague??s.league};if(e.type==='trait'&&g){const t=pick(traits.filter(t=>!g.traits.includes(t)));g.traits.push(t);log(g.name+' entwickelt: '+t)}if(e.type==='prospect'){const r=makeGladiator(0);r.age=18;r.potential=98;delete r.caps;ensurePotentials(r);r.price=150;r.name='Junges Talent';s.market.push(r)}}else if(e.type==='wages'&&g)g.stats.morale=Math.max(15,g.stats.morale-12);s.event=null;persist();return yes?'Ereignis angenommen.':'Ereignis abgelehnt.'}
function recovery(){if(s.roster.length>=3&&s.gold>=100)return 'Die Schule ist noch handlungsfähig.';if(s.day-s.recoveryDay<7)return 'Nächste Notfallhilfe an Tag '+(s.recoveryDay+7)+'.';s.recoveryDay=s.day;s.gold+=350;log('Die Arena-Gilde gewährt 350 Gold für den Wiederaufbau.');persist();return '350 Gold Wiederaufbauhilfe. Gefallene bleiben verloren.'}
function selectedTeam(){return s.teams[s.teamIndex].map(id=>s.roster.find(g=>g.id===id)).filter(Boolean)}
function validateTeam(type='league',tournamentId){const team=selectedTeam();if(team.some(g=>g.smithAssigned))return 'Ein Gladiator arbeitet in der Schmiede. Löse zuerst seine Zuweisung.';if(team.length!==3)return 'Wähle genau drei Gladiatoren unter TEAM.';if(team.some(g=>g.age<18))return 'Nur Erwachsene ab 18 Jahren dürfen antreten.';if(team.some(g=>g.dead||g.body.head.missing||g.body.chest.hp<5))return 'Ein Gladiator ist nicht kampffähig.';if(type==='tournament'){const t=tournaments.find(x=>x.id===tournamentId);if(t.id==='melee'&&team.some(g=>itemStats(gear(g,'weapon'))?.ammo))return 'Nur Nahkampfwaffen sind zugelassen.';if(t.id==='light'&&team.some(g=>weightGear(g)>12))return 'Höchstens 12 kg Ausrüstung je Gladiator.';if(t.id==='ranged'&&team.some(g=>!itemStats(gear(g,'weapon'))?.ammo))return 'Alle drei brauchen Fernkampfwaffen.';if(t.id==='veteran'&&team.some(g=>g.fights<10))return 'Jeder Gladiator braucht zehn Kämpfe.';if(t.id==='champion'&&s.league<5)return 'Erst ab Champion-Liga.'}return ''}


const moveNames={pierce:'Durchstich',combo:'Zufällige 2er-/3er-/4er-Kombo',groundFinish:'Bodenabschluss',shieldBash:'Schildstoß',rearFinish:'Griff von hinten',slash:'Hieb',overhead:'Überkopfschlag',kick:'Tritt',rise:'Aufstehen',recover:'Standfestigkeit nach Treffern',dodge:'Ausweichen',charge:'Ansturm',backstep:'Rücksprung',thrust:'Stich',spin:'Drehschlag',sand:'Sandtritt'};
const statHelp={strength:'Erhöht den Nahkampfschaden. Wächst durch Schläge und Anstürme.',stamina:'Erhöht die maximale Kampfenergie. Wächst beim Laufen, Angreifen und Ausweichen.',condition:'Beschleunigt die Energieregeneration. Wächst bei Anstrengung im Kampf.',agility:'Erhöht Lauftempo und erschwert gegnerische Treffer. Wächst beim Bewegen und Ausweichen.',dexterity:'Verbessert Waffenführung, Trefferchance und Angriffstempo. Wächst beim Angreifen.',reflex:'Verbessert Reaktion, Konter und Ausweichentscheidungen. Wächst bei Blocks und Ausweichversuchen.',precision:'Verbessert Fernkampftreffer und kritische Treffer. Wächst durch Würfe und gezielte Treffer.',block:'Erhöht die Chance auf Schild- und Waffenblocks. Wächst durch Blockversuche und erfolgreiche Blocks.',balance:'Verringert Rückstoß. Wächst beim Blocken, Abfangen von Treffern und Anstürmen.',toughness:'Verringert den Schmerz durch Verletzungen. Wächst bei erlittenen Treffern.',pain:'Verringert den Leistungsverlust durch Schmerzen. Wächst beim Durchstehen von Treffern.',will:'Verringert Rückzug und Aufgabe bei Gefahr. Wächst beim Weiterkämpfen und Durchstehen von Treffern.',aggression:'Erhöht die Angriffshäufigkeit. Wächst durch Angriffsversuche.',tactics:'Verbessert Zielwahl und Positionierung. Wächst bei Zielentscheidungen.',teamwork:'Verbessert Hilfe für angegriffene Teamkameraden. Wächst bei tatsächlicher Unterstützung.',experience:'Verbessert Treffer, Entscheidungen und Reaktionen. Wächst bei Kampfaktionen.',morale:'Aktuelle Zuversicht: beeinflusst den Schaden. Schwankt mit Sieg, Niederlage, Erholung und Ereignissen; kein verteilbarer Skill.'};
const moveHelp={pierce:'Kräftiger Stich durch ein bereits verletztes Körperteil. Die Klinge wird anschließend herausgezogen. Der Schaden zählt einmalig als Durchstich. Nur geeignete Klingen- und Stichwaffen.',combo:'Nach jedem Schlag besteht eine Chance von 50 % auf einen weiteren Angriff, bis maximal vier Schläge. Folgeangriffe erhalten den bestehenden Trefferbonus. Verletzungen, Abwehr, Abstand und Ausdauer können die Serie beenden.',groundFinish:'Abschlussstich mit Klingen oder Abschlussschlag mit Schlagwaffen gegen am Boden liegende Gegner. Deutliches Ausholen, unterbrechbar und kein garantierter tödlicher Treffer. Wächst durch tatsächliche Versuche.',shieldBash:'Naher Stoß mit einem benutzbaren Schild. Verbraucht Ausdauer, stößt zurück und kann taumeln lassen. Wird durch tatsächlich ausgeführte Schildstöße trainiert.',rearFinish:'Abwehrbarer Abschlussangriff gegen abgelenkte oder bereits verletzte Gegner von hinten, nur mit einer Nahkampf-Klingenwaffe und zwei brauchbaren Armen. Dolche erhalten einen Bonus. Angriffsfertigkeit und Geschick werden gegen Reflexe, Blocken und Erfahrung geprüft. Kein garantierter Kill.',slash:'Wächst durch ausgeführte normale Hiebe und verbessert deren Schaden.',overhead:'Wächst durch ausgeführte Überkopfschläge. Mehr Schaden und Durchschlag, längeres Ausholen.',kick:'Wächst nur durch ausgeführte Tritte. Kurze Reichweite, verbraucht Energie, stößt Gegner zurück und kann sie aus dem Gleichgewicht bringen.',rise:'Wächst durch tatsächliche Aufstehversuche. Verkürzt das Aufrichten und senkt die Chance, erneut zu stürzen. Verletzungen, Blutverlust, Erschöpfung und verbrauchte Kampfenergie verlängern die Bodenphase deutlich. Verletzte oder fehlende Beine bleiben entscheidend.',recover:'Wächst beim Abfangen schwerer Treffer und beim Erholen vom Taumeln. Verkürzt das Taumeln.',sand:'Trick auf kurze Distanz. Sand stört kurz die Sicht; der Gegner reibt sich die Augen. Wächst nur durch den tatsächlichen Versuch.',thrust:'Wächst durch ausgeführte Stiche mit Dolch, Schwert, Speer oder Dreizack. Verbessert den Durchschlag.',spin:'Wächst durch versuchte Drehschläge mit geeigneten Nahkampfwaffen. Kann nahe Gegner treffen, kostet mehr Energie.',dodge:'Wächst bei kurzen Ausweichschritten und vermiedenen Treffern. Verbessert Reaktion und Erholungszeit. Mit gezogenem Bogen oder gezogener Armbrust sind Ausweichreaktion und Ausweicherfolg stark reduziert (Faktor 0,25). Nach dem Wechsel zur Nahkampfwaffe gilt wieder der normale Wert. Keine Rolle und keine garantierte Unverwundbarkeit.',charge:'Wächst beim Ansturmversuch und ausgeführten Sturmangriff. Erhöht Tempo und Bonusschaden; braucht Anlauf.',backstep:'Wächst beim Rücksprung nach Treffern. Verbessert Distanz, Ausweichchance und Erholungszeit.'};
function stableRoll(g,key){let h=2166136261;for(const c of g.id+':'+key)h=Math.imul(h^c.charCodeAt(0),16777619);h^=h>>>16;h=Math.imul(h,0x45d9f3b);h^=h>>>16;return(h>>>0)/4294967296}
function bernoulliValue(mean,n=64){let hits=0,p=clamp((mean-1)/99,.01,.98);for(let i=0;i<n;i++)if(rng()<p)hits++;return Math.round(1+99*hits/n);}
function personalCap(g,key,value){let hits=0,p=.52+g.potential*.0026;for(let i=0;i<32;i++)if(stableRoll(g,key+':trial:'+i)<p)hits++;return Math.max(Math.ceil(value||0),Math.round(1+99*hits/32));}
function ensurePotentials(g){for(const k of ['pierce','combo','dodge','thrust','spin','sand','slash','overhead','kick','rise','recover','rearFinish','shieldBash','groundFinish'])g.moves[k]??=Math.round(3+stableRoll(g,'initial:'+k)*7);if(!g.caps){const cap=(key,value)=>personalCap(g,key,value);g.caps={stats:Object.fromEntries(Object.entries(g.stats).map(([k,v])=>[k,cap('stat:'+k,v)])),weapons:Object.fromEntries(weaponDefs.map(w=>[w.id,cap('weapon:'+w.id,g.mastery?.[w.id]||10)])),moves:Object.fromEntries(Object.entries(g.moves).map(([k,v])=>[k,cap('move:'+k,v)])),body:Object.fromEntries(parts.map(([id])=>[id,{strength:cap('body-strength:'+id,g.body[id].strength),agility:cap('body-agility:'+id,g.body[id].agility)}]))};}for(const k of Object.keys(g.moves))g.caps.moves[k]??=personalCap(g,'move:'+k,g.moves[k]);delete g.talents;delete g.level;delete g.xp;return g.caps}

function learningValue(g,group,key){if(group==='body'){const [id,k]=key.split('.');return g.body[id][k]}return (group==='weapons'?g.mastery:g[group])[key]}
function learningCap(g,group,key){if(group==='body'){const [id,k]=key.split('.');return g.caps.body[id][k]}return g.caps[group]?.[key]??0}
function addLearning(g,group,key,amount){const cap=learningCap(g,group,key),value=learningValue(g,group,key);if(!Number.isFinite(value)||!cap||amount<=0)return 0;const gain=Math.max(0,Math.min(cap,value+amount)-value);if(group==='body'){const [id,k]=key.split('.');if(g.body[id].missing)return 0;g.body[id][k]+=gain}else(group==='weapons'?g.mastery:g[group])[key]+=gain;return gain}
/* Lerntempo der Gladiatoren (Wunsch Thomas 2026-10-25: dreimal so schnell). Gilt für Kampf, Abenteuer, Boxen und Ereignisse; Obergrenzen (Potenzial) unverändert. 1 = vorheriges Tempo. */
const LEARN_SPEED=3;
function learn(a,group,key,amount){if(s.battle?.benchmark)return 0;if(!s.battle||s.battle.finale||s.battle.paused||a.g.dead||a.g.retired||a.down||a.surrendered||!s.battle.actors.includes(a))return 0;const g=a.g;if(!g.caps)ensureCareer(g);if(group==='weapons'&&!weaponDefs.some(w=>w.id===key))return 0;const building=group==='weapons'?(weaponDefs.find(w=>w.id===key)?.ammo?'archery':'weapons'):group==='moves'?'training':['strength','stamina','condition'].includes(key)?key==='strength'?'strength':'endurance':['tactics','teamwork'].includes(key)?'tactics':'training';let rate=2*LEARN_SPEED*(.7+g.potential/150)*(g.traits.includes('Schneller Lerner')?1.2:1)*(g.age>36?.75:1)*(1+(s.buildings[building]||0)*.03);if(group==='weapons'&&lesson(g,key).teacher)rate*=1.15;const gain=addLearning(g,group,key,amount*rate*(.08+.92*Math.pow(Math.max(0,(learningCap(g,group,key)-learningValue(g,group,key))/Math.max(1,learningCap(g,group,key))),.65)));a.learning??={};const path=group+':'+key;a.learning[path]=(a.learning[path]||0)+gain;return gain}
function applyLearningBonus(a){if(a.learningBonusApplied)return;a.learningBonusApplied=true;if((a.xpMultiplier||1)<=1||a.g.dead)return;for(const [path,amount]of Object.entries(a.learning||{})){const [group,key]=path.split(':');a.learning[path]+=addLearning(a.g,group,key,amount*((a.xpMultiplier||1)-1))}}
function learningLabel(path){const [group,key]=path.split(':');if(group==='stats')return stats[key];if(group==='moves')return moveNames[key];if(group==='weapons')return weaponDefs.find(w=>w.id===key)?.name||key;const [id,k]=key.split('.');return partName(id)+' · '+(k==='strength'?'Kraft':'Beweglichkeit')}
const mantleNames=['Leinen des Neulings','Staub des Sandes','Band des Kämpfers','Kupfersaum','Mantel des Siegers','Eid der Arena','Bronzeflamme','Wolfsfell','Rote Düne','Silbersaum','Stolz des Ludus','Karmesinband','Adlerschwinge','Goldene Amphore','Eiserner Lorbeer','Banner der Provinz','Löwenfell','Purpursaum','Triumph von Marmor','Stern von Rom','Mantel des Tribuns','Schild des Volkes','Rubinbanner','Nacht des Champions','Glut des Imperiums','Goldener Adler','Lorbeer des Senats','Königlicher Purpur','Sonnenbrokat','Eid der Unsterblichen','Sturm des Mars','Krone der Asche','Saphir des Himmels','Mantel des Prätors','Flügel der Aurora','Kaisersammet','Löwe des Firmaments','Purpur der Titanen','Gewebe des Schicksals','Gold der Ewigkeit','Sternenlorbeer','Feuer des Olymp','Triumph der Götter','Banner der Äonen','Mantel des Weltenherrschers','Sonne des Unsterblichen','Seide der Legenden','Krone der Zeiten','Letzter Morgenstern','Mantel der Unendlichkeit'];
const mantles=mantleNames.map((name,i)=>({tier:i+1,name,fame:Math.round(20*(Math.pow(1.24,i+1)-1)/.24),color:['#706348','#3f7974','#984332','#465786','#755183','#b18739','#466b49','#923d62','#356d88','#9b713b'][i%10],trim:i<10?'#a48c65':i<25?'#d0bb88':i<40?'#e7c566':'#f6df96',pattern:Math.floor(i/10),length:22+Math.floor(i/5)*2}));
function mantle(g){return [...mantles].reverse().find(m=>g.fame>=m.fame)||null}
function nextMantle(g){return mantles.find(m=>g.fame<m.fame)||null}

// Existing saves are extended in place. Recorded item rolls never change on reload.
function ensureCareer(g){if(g.moves&&g.caps){for(const k of ['pierce','combo']){g.moves[k]??=Math.round(3+stableRoll(g,'initial:'+k)*7);g.caps.moves[k]??=personalCap(g,'move:'+k,g.moves[k]);}}if(g.mastery&&g.caps){for(const id of ['bow','crossbow']){g.mastery[id]??=10;g.caps.weapons[id]??=Math.max(g.mastery[id],g.potential||60);}}if(g.caps&&g.mastery&&g.killHistory&&g.moves?.thrust!==undefined&&g.caps.moves.thrust!==undefined&&g.moves.sand!==undefined&&g.caps.moves.sand!==undefined&&g.moves.recover!==undefined&&g.caps.moves.recover!==undefined&&g.moves.rearFinish!==undefined&&g.caps.moves.rearFinish!==undefined&&g.moves.shieldBash!==undefined&&g.caps.moves.shieldBash!==undefined&&g.moves.groundFinish!==undefined&&g.caps.moves.groundFinish!==undefined){delete g.level;delete g.xp;delete g.talents;return g;}ensureIdentity(g);if(!g.mastery){const family=id=>['spear','trident','halberd'].includes(id)?'spear':['shortbow','longbow','sling','gastraphetes'].includes(id)?'bow':['javelin','throwaxe'].includes(id)?'throw':'sword';g.mastery=Object.fromEntries(weaponDefs.map(w=>[w.id,clamp(g.skills?.[family(w.id)]??10,1,100)]))}for(const w of weaponDefs)g.mastery[w.id]??=10;if(g.trainingWeapon&&!weaponDefs.some(w=>w.id===g.trainingWeapon))g.trainingWeapon='short';if(!g.killHistory){g.killHistory=[];g.unrecordedKills=g.kills||0}if(g.retired&&!g.trainerCaps)g.trainerCaps=copy(g.mastery);ensurePotentials(g);return g}
function mastery(g,id){ensureCareer(g);return g.mastery[id]||0}

function combatPractice(g,id,amount=.008){const a=s.battle?.actors.find(a=>a.g.id===g.id);if(a)learn(a,'weapons',id,amount)}
function lesson(g,id=gear(g,'weapon')?.def||'fist'){ensureCareer(g);const teacher=s.trainers.filter(t=>t.retired&&t.trainerEnabled!==false&&t.trainerCaps?.[id]>mastery(g,id)).sort((a,b)=>b.trainerCaps[id]-a.trainerCaps[id])[0];return {id,teacher,cap:teacher?Math.min(teacher.trainerCaps[id],g.caps.weapons[id]):0,rate:teacher?.15:0}}

function setTrainingWeapon(id,weapon){const g=s.roster.find(g=>g.id===id);if(g&&weaponDefs.some(w=>w.id===weapon)){g.trainingWeapon=weapon;persist()}}
function toggleTrainer(id){const t=s.trainers.find(t=>t.id===id&&t.retired);if(!t)return 'Nur eigene pensionierte Gladiatoren können unterrichten.';t.trainerEnabled=t.trainerEnabled===false;persist();return t.trainerEnabled?'Mentor für Kampferfahrung aktiviert.':'Mentor pausiert.'}
s.smiths??=[];
for(const g of [...s.roster,...s.market,...s.trainers,...(s.battle?.actors.map(a=>a.g)||[])])ensureCareer(g);
const forgeCategories=[...weaponDefs.map(d=>({key:'weapon/'+d.id,name:d.name,kind:'weapon',def:d.id})),...armorDefs.map(d=>({key:'armor/'+d.id,name:d.name,kind:'armor',def:d.id})),...shieldDefs.map(d=>({key:'shield/'+d.id,name:d.name,kind:'shield',def:d.id}))];
// Sum of Bernoulli trials: bell-shaped binomial distribution, no clipped upper tail.
// P(Soll=100) = .58^24, approximately 1 in 475,000 per category.
function smithRoll(p=.58){let successes=0;for(let n=0;n<24;n++)if(rng()<p)successes++;return successes;}
function smithPotential(){return Math.round(20+80*smithRoll()/24);}
function ensureSmith(t){t.categories??={};for(const c of forgeCategories){if(!t.categories[c.key]){const current=clamp(t.skill??(8+2*smithRoll(.5)),1,100);t.categories[c.key]={current,potential:Math.max(current,smithPotential())}}}t.crafted??=0;delete t.skill;delete t.level;delete t.xp;return t}
function ensureGladiatorSmith(g){if(!g.smith){let seed=2166136261;for(const c of g.id)seed=Math.imul(seed^c.charCodeAt(0),16777619);const r=()=>{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return(seed>>>0)/4294967296};const bin=p=>{let n=0;for(let j=0;j<24;j++)if(r()<p)n++;return n};g.smith={};for(const c of forgeCategories){const current=Math.round(1+99*bin(19/99)/24);g.smith[c.key]={current,potential:Math.max(current,Math.round(20+80*bin(.58)/24))}}}for(const c of forgeCategories)g.smith[c.key]??={current:30,potential:65};return g.smith;}
function forgeStaff(){return s.roster.filter(g=>g.smithAssigned&&!g.dead&&!g.retired);}
function forgeKnowledge(key){const staff=forgeStaff();for(const g of staff)ensureGladiatorSmith(g);const lead=staff.sort((a,b)=>b.smith[key].current-a.smith[key].current)[0];return lead?{...lead.smith[key],lead}:{current:0,potential:0,lead:null};}
function assignSmith(id){if(s.battle)return 'Während eines Kampfes nicht möglich.';const g=s.roster.find(g=>g.id===id);if(!g)return 'Gladiator nicht gefunden.';ensureGladiatorSmith(g);g.smithAssigned=!g.smithAssigned;persist();return g.name+(g.smithAssigned?' arbeitet jetzt in der Schmiede.':' steht wieder für Arenakämpfe bereit.');}
function progressForge(i,base=.12){const k=forgeKnowledge(i.kind+'/'+i.def);if(!k.lead)return 0;const gain=Math.min(k.potential-k.current,base*Math.pow(Math.max(0,(k.potential-k.current)/Math.max(1,k.potential)),.75));k.lead.smith[i.kind+'/'+i.def].current+=gain;k.lead.smithCrafted=(k.lead.smithCrafted||0)+1;return gain;}
function smithHireCost(){return 0}
function hireSmith(){return 'Weise einen Gladiator aus deinem Kader der Schmiede zu.'}
function trainSmith(){return 'Gladiatoren lernen das Schmieden durch Herstellung.'}
function selectSmith(){return forgeStaff()[0]||null}
function reforgeCost(i){return Math.round(Math.max(35,itemPrice(i.kind,i.def,i.q)*.18)*(1+(i.reforges||0)*.08))}
function rollForge(i){const k=forgeKnowledge(i.kind+'/'+i.def),roll=()=>.9+.2*Math.pow(rng(),1/(.65+k.current/100));i.rolls=Object.fromEntries(['damage','speed','range','weight','pen','block','crit','protection','area'].map(key=>[key,key==='weight'?2-roll():roll()]));i.maxDurability=Math.round((100+i.q*10)*roll());i.durability=i.maxDurability;i.maker=k.lead?.name||'Schmiede';i.forgedDay=s.day;i.forgeRange=.10;return progressForge(i)}
function reforge(){return 'Umschmieden ist nicht mehr möglich.'}
function craft(kind,def,q,material='metal'){if(s.battle)return 'Während eines Kampfes nicht möglich.';if(!forgeStaff().length)return 'Weise zuerst einen Gladiator der Schmiede zu.';if(!forgeCategories.some(c=>c.kind===kind&&c.def===def)||!Number.isInteger(q)||q<0||q>6)return 'Ungültige Kategorie.';if(s.inventory.length>=storageCapacity())return 'Lager ist voll.';const cost=Math.round(itemPrice(kind,def,q)*.9);if(s.gold<cost)return 'Nicht genug Gold.';s.gold-=cost;s.stats.spent+=cost;const i=makeItem(kind,def,q,material);rollForge(i);s.inventory.push(i);persist();return itemName(i)+' hergestellt von '+i.maker+'.'}
for(const g of [...s.roster,...s.market,...s.trainers])ensureGladiatorSmith(g);
s.event=null;
if(!s.standardRecruitMigration){refreshMarket(true);s.standardRecruitMigration=true;}
for(const g of [...s.roster,...s.market,...s.trainers,...(s.battle?.actors.map(a=>a.g)||[])]){ensureGladiatorSmith(g);if(!roles.includes(g.role))g.role=['Flankierer','Duellist'].includes(g.role)?'Assassine':'Soldat';}
// Remove discontinued gear, including equipped and in-flight weapons, without touching careers.
const removedWeapons=new Set(['shortbow','longbow','gastraphetes','sling']);
const retiredGear=new Set(s.inventory.filter(i=>i.kind==='weapon'&&removedWeapons.has(i.def)).map(i=>i.id));
s.inventory=s.inventory.filter(i=>!retiredGear.has(i.id));
for(const g of [...s.roster,...s.market,...s.trainers,...(s.battle?.actors.map(a=>a.g)||[])]){for(const slot of ['weapon','secondary']){if(retiredGear.has(g.equipment?.[slot]))g.equipment[slot]=null;if(g.enemyGear?.[slot]&&removedWeapons.has(g.enemyGear[slot].def))g.enemyGear[slot]=null;}for(const id of removedWeapons){if(g.mastery)delete g.mastery[id];if(g.trainerCaps)delete g.trainerCaps[id]}}
