function arenaPrize(b,won){const L=M.leagues[b.league],champion=b.champion?1.3:1;if(!won)return b.openArena?0:Math.round(L.reward*.18);const sponsor=S.sponsor?1+S.sponsor.bonus:1,fame=1+Math.min(.25,b.actors.filter(a=>a.team===0).reduce((n,a)=>n+a.g.fame,0)/10000);return L.reward*champion*sponsor*fame;}
