 if(usableShield(a)&&a.energy>10){a.a=Math.atan2(-incoming.vy,-incoming.vx);a.block=true;a.guardTime=.5;a.missileGuard=.18;a.state='guard';a.moveSpeed=0;return true;}
 if(a.energy<18||a.dodgeCD>0||!limbState(a.g).canBurst)return false;
 const an=Math.atan2(incoming.vy,incoming.vx);a.dodgeAngle=an+Math.PI/2*a.side;a.dodgeTimer=.24;a.dodgeCD=2.6-a.g.moves.dodge*.008;a.energy-=13;a.dodges++;a.state='dodge';a.projectileDodge=.4;M.learn(a,'moves','dodge',.02);M.learn(a,'stats','reflex',.006);return true;
