function rearMultiplier(a,b){return Math.abs(angleDiff(angle(b,a),b.a))>Math.PI*2/3?2.2:1}
function engagedElsewhere(a,t){const ally=actorById(t.target);if(!ally||ally.id===a.id||ally.team!==a.team||ally.down||ally.g.dead||ally.surrendered||ally.fallTimer>0||ally.kneeTimer>0||t.down||t.g.dead||t.surrendered)return false;return dist(t,ally)<Math.min(95,effective(t).range)+25&&((ally.target===t.id&&(ally.wind>0||ally.pendingStrike||ally.swing>0))||t.wind>0||t.pendingStrike||t.swing>0||(t.engagedWith===ally.id&&t.engagedUntil>S.battle.time));}
function startFlank(a,t){if(!t||!engagedElsewhere(a,t)||!limbState(a.g).canBurst||a.energy<(a.g.role==='Assassine'?19:20)||a.retreat>0||a.netTimer>0||a.blindTimer>0||a.flankCD>0||weapon(a).ammo||dist(a,t)>250)return false;a.flankTarget=t.id;a.flankSkill=(a.g.stats.tactics*.35+a.g.stats.experience*.2+a.g.stats.agility*.25+a.g.stats.teamwork*.2)/100;a.flankTimer=(a.g.role==='Assassine'?4:2.2)+a.flankSkill*2;a.flankCD=a.g.role==='Assassine'?4.5:3.5;a.flankSide=angleDiff(angle(t,a),t.a)>=0?1:-1;a.flankStarted=S.battle.time;a.flanks=(a.flanks||0)+1;return true;}
function flankVector(a,t,ef){if(!(a.flankTimer>0)||a.flankTarget!==t.id||!engagedElsewhere(a,t)||!limbState(a.g).canBurst||a.energy<12||a.retreat>0||a.netTimer>0||a.blindTimer>0){a.flankTimer=0;return null;}if(rearMultiplier(a,t)>1&&dist(a,t)<(gripBlade(ef.w)?46:ef.range+t.r)){a.flankTimer=0;a.approachUntil=0;return null;}if(a.g.role==='Assassine'&&S.battle.time-(a.flankStarted||0)>1.0&&dist(a,t)<ef.range+t.r){a.flankTimer=0;a.flankCD=2.5;a.approachUntil=0;return null;}const rel=angleDiff(angle(t,a),t.a),side=a.flankSide||(rel>=0?1:-1),rear=Math.abs(rel)>2.05,radius=rear&&gripBlade(ef.w)?38:Math.abs(rel)<1.45?Math.max(85,effective(t).range+25):Math.max(42,Math.min(65,ef.range)),ang=rear?t.a+Math.PI:t.a+rel+side*(.95+(a.flankSkill||0)*.65),x=t.x+Math.cos(ang)*radius,y=t.y+Math.sin(ang)*radius,d=Math.hypot(x-a.x,y-a.y);a.state='flank';return {x:(x-a.x)/Math.max(1,d),y:(y-a.y)/Math.max(1,d)};}
function hammerCrush(a,b,id,w,dmg,crit){const p=b.g.body[id],blunt=['hammer','mace','club'].includes(w.id);if(!blunt||!['ls','rs','lua','rua','lfa','rfa','lh','rh','lt','rt','lsh','rsh','lf','rf'].includes(id)||p.missing||p.fracture?.crushed||dmg<T.crushMinDmg||p.hp>T.crushMaxHp||rng()>(crit?T.crushCrit:T.crushChance)*(w.id==='hammer'?1:T.crushNonHammer))return false;const held=weapon(b);p.hp=Math.min(p.hp,T.crushHpSet);p.fracture={days:T.crushDays,total:T.crushDays,severe:true,crushed:true};p.pain=Math.max(p.pain,85);p.chronic=Math.max(p.chronic,8);p.grade=M.injuryGrade(p);M.noteInjury(b.g,id,'Trümmerbruch');M.addScar(b.g,id,'Schwerer Trümmerbruch');if(['lt','rt','lsh','rsh','lf','rf'].includes(id))knockdown(b,'Trümmerbruch am Bein',3.6);if(['ls','lua','lfa','lh'].includes(id))dropGear(b,'shield');if(held.hand==='r'?['rs','rua','rfa','rh'].includes(id):['ls','lua','lfa','lh'].includes(id))dropGear(b,held.item?.id===M.gear(b.g,'secondary')?.id?'secondary':'weapon');floater(b.x,b.y-64,'TRÜMMERBRUCH','#edbf88');battleLog(a.g.name+' verursacht mit '+w.name+' einen Trümmerbruch: '+M.partName(id)+' von '+b.g.name+'.');M.sound?.('fall');M.shake=Math.max(M.shake,4);return true;}
