function presentationStep(dt){stepFinishPush(dt);const b=S.battle;if(!b||b.paused)return;if(b.benchmark)b.cinematic=null;for(const a of b.actors){if(a.neckFinishTimer>0)a.neckFinishTimer=Math.max(0,a.neckFinishTimer-dt*(b.cinematic?.18:1));if(a.finishReaction!==undefined&&!b.actors.some(x=>x.finishPush?.target===a.id))a.finishReaction=Math.min(1.2,a.finishReaction+dt);}if(b.verdictCamera)b.verdictCamera.mix=Math.min(1,(b.verdictCamera.mix||0)+dt*3);if(b.cinematic){b.cinematic.left=Math.max(0,b.cinematic.left-dt);if(!b.cinematic.left)b.cinematic=null;}}
