consolidateTeams();
const ranged=['bow','crossbow'],melee=M.weaponDefs.filter(w=>!w.ammo).map(w=>w.id),slots=['weapon','secondary','shield',...M.armorDefs.map(d=>d.id)];
M.classSpecs.Fernkämpfer.weapons=ranged;M.classSpecs.Soldat.weapons=melee;
function person(g){g.locks??={};g.reserve??=false;g.available??=true;g.ammoLoad??=M.gear(g,'weapon')?.def==='crossbow'?8:12;g.smithAssigned=false;return g;}
for(const g of S.roster)person(g);S.market=[];S.blindRecruitment=true;
function audit(message){S.army.audit.unshift({day:S.day,message});S.army.audit=S.army.audit.slice(0,120);return message;}
function plan(){return S.teamPlans[S.teamIndex];}
function teamOf(id){return S.teams.map((t,i)=>t.includes(id)?S.teamPlans[i]?.name:null).filter(Boolean).join(', ');}
function bestWeapon(g,range=false,potential=false){const values=potential?g.caps.weapons:g.mastery;return (range?ranged:melee.filter(id=>M.allowedMelee(g,id))).map(id=>({id,value:values[id]||1})).sort((a,b)=>b.value-a.value)[0];}
function combatValues(g){const projected={...g,stats:{...g.caps.stats},body:Object.fromEntries(Object.entries(g.body).map(([id,p])=>[id,{...p,hp:100-p.chronic}]))};return {current:M.power(g),maximum:Math.max(M.power(g),M.power(projected))};}
